contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 depositAmount) public {
        // Restrict to admissible domain: contract balance must not overflow and be positive
        vm.assume(initialBalance > 0);
