        vm.assume(depositAmount <= type(uint128).max);
        vm.assume(initialBalance + depositAmount <= type(uint128).max);

        // Fund the contract to set up a known balance
        vm.deal(address(c), initialBalance);

        // Optionally deposit more via the Owner to test various balance scenarios
        if (depositAmount > 0) {
            vm.deal(c.Owner(), depositAmount);
            vm.prank(c.Owner());
            c.Command{value: depositAmount}(address(c), "");
        }

        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = c.Owner().balance;

        // Owner calls withdraw
        vm.prank(c.Owner());
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("withdraw()"));
        require(ok, "withdraw call failed");

        uint256 ownerBalanceAfter = c.Owner().balance;

        // Invariant: Owner's balance increased by exactly the pre-withdraw contract balance
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + balanceBefore);
    }
